/* Detourr shared code. Loaded by the homepage and every game page, in this order:
   core.js, catalog.js, lib/*.js (only the ones a game needs), the game's own code, app.js. */
/* core.js: helpers every game can use (el, S, beep, sound, 3D engine, shared game helpers) */
const $=(s,r=document)=>r.querySelector(s);
function el(tag,props,...kids){const e=document.createElement(tag);props=props||{};for(const k in props){const v=props[k];if(k==='class')e.className=v;else if(k==='style')e.style.cssText=v;else if(k==='html')e.innerHTML=v;else if(k.slice(0,2)==='on')e.addEventListener(k.slice(2),v);else e.setAttribute(k,v)}for(const c of kids.flat()){if(c==null)continue;e.append(c.nodeType?c:document.createTextNode(c))}return e}
const rand=n=>Math.floor(Math.random()*n);
const pick=a=>a[rand(a.length)];
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=rand(i+1);[a[i],a[j]]=[a[j],a[i]]}return a};
const S={get(k,d){try{const v=localStorage.getItem('unb_'+k);return v==null?d:JSON.parse(v)}catch(e){return d}},set(k,v){try{localStorage.setItem('unb_'+k,JSON.stringify(v))}catch(e){}}};
let muted=S.get('muted',false),AC=null;
function beep(f,d,type,v){if(muted)return;try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();if(AC.state!=='running')AC.resume();const t=AC.currentTime,o=AC.createOscillator(),g=AC.createGain();o.type=type||'sine';o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(v||.07,t);g.gain.exponentialRampToValueAtTime(.0001,t+(d||.1));o.connect(g);g.connect(AC.destination);o.start(t);o.stop(t+(d||.1)+.02)}catch(e){}}
function syncMute(){const t='Sound: '+(muted?'off':'on');$('#mute').textContent=t;{const m=$('#muteHome');if(m)m.textContent=t}}
[$('#mute'),$('#muteHome')].filter(Boolean).forEach(b=>b.addEventListener('click',()=>{muted=!muted;S.set('muted',muted);syncMute()}));
syncMute();
const KEYDIR={arrowup:[0,-1],arrowdown:[0,1],arrowleft:[-1,0],arrowright:[1,0],w:[0,-1],s:[0,1],a:[-1,0],d:[1,0]};
function swipe(c,target,fn){let sx=null,sy=0;c.on(target,'touchstart',e=>{const t=e.touches[0];sx=t.clientX;sy=t.clientY},{passive:true});c.on(target,'touchend',e=>{if(sx==null)return;const t=e.changedTouches[0],dx=t.clientX-sx,dy=t.clientY-sy;sx=null;if(Math.max(Math.abs(dx),Math.abs(dy))<24)return fn(0,0);Math.abs(dx)>Math.abs(dy)?fn(Math.sign(dx),0):fn(0,Math.sign(dy))})}
function dpad(fn){const b=(t,dx,dy,pos)=>el('button',{type:'button',style:pos,'aria-label':t,onpointerdown:e=>{e.preventDefault();fn(dx,dy)}},t);
  return el('div',{class:'dpad'},b('↑',0,-1,'grid-column:2;grid-row:1'),b('←',-1,0,'grid-column:1;grid-row:2'),b('↓',0,1,'grid-column:2;grid-row:2'),b('→',1,0,'grid-column:3;grid-row:2'))}
function canvasPos(cv,e){const r=cv.getBoundingClientRect();return{x:(e.clientX-r.left)*cv.width/r.width,y:(e.clientY-r.top)*cv.height/r.height}}
function rr(x,X,Y,W,H,R){x.beginPath();x.roundRect?x.roundRect(X,Y,W,H,R):x.rect(X,Y,W,H)}
function banner(x,W,H,t1,t2){x.fillStyle='rgba(29,26,47,.78)';x.fillRect(0,H/2-70,W,140);x.fillStyle='#FFD23F';x.textAlign='center';x.font='40px "Bagel Fat One", sans-serif';x.fillText(t1,W/2,H/2-2);x.fillStyle='#FFFDF6';x.font='600 18px Figtree, sans-serif';x.fillText(t2,W/2,H/2+36)}
const SILENT='data:audio/wav;base64,';
let silentEl=null;
function unlockAudio(){try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();if(AC.state!=='running'){AC.resume();const bf=AC.createBuffer(1,1,22050),src=AC.createBufferSource();src.buffer=bf;src.connect(AC.destination);src.start(0)}}catch(e){}
  if(!muted){try{if(!silentEl){silentEl=new Audio(SILENT);silentEl.loop=true;silentEl.setAttribute('playsinline','');silentEl.volume=.01}if(silentEl.paused)silentEl.play().catch(()=>{})}catch(e){}}}
['pointerdown','touchend','keydown','click'].forEach(ev=>document.addEventListener(ev,unlockAudio,{capture:true,passive:true}));
document.addEventListener('visibilitychange',()=>{if(document.hidden){silentEl&&silentEl.pause()}});
const G=[];
/* games load after the catalog: a game's full definition replaces its catalog entry, keeping the catalog's listing details */
G.push=function(...a){for(const g of a){const i=this.findIndex(x=>x.id===g.id);if(i>=0){const c=this[i];for(const k in c)if(k!=='fmt'||!g.fmt)g[k]=c[k];this[i]=g}else Array.prototype.push.call(this,g)}return this.length};
